    13	export interface Request {
    14	  version: 1; id: string; cwd: string; journal: string; output: string; prompt: string;
    15	  model: string; seconds: number; checkpointSeconds?: number; sessions: SessionSummary[];
    16	  mode?: 'run' | 'inspect';
